WITH d AS (
  SELECT FMEL_UPD_D, NAME, OGC_FID,
         ST_Distance_Spheroid(geometry::GEOMETRY, ST_Point(103.85, 1.29)) AS dist_m
  FROM sg_parks
), r AS (
  SELECT FMEL_UPD_D, NAME, dist_m,
         ROW_NUMBER() OVER (PARTITION BY FMEL_UPD_D ORDER BY dist_m, OGC_FID) AS rn
  FROM d
)
SELECT FMEL_UPD_D, NAME, dist_m FROM r WHERE rn = 1 ORDER BY FMEL_UPD_D;

WITH pairs AS (
  SELECT a.OGC_FID AS fid, a.NAME AS name,
         ST_Distance_Spheroid(a.geometry::GEOMETRY, b.geometry::GEOMETRY) AS d
  FROM sg_parks a
  JOIN sg_parks b ON a.OGC_FID <> b.OGC_FID
), r AS (
  SELECT fid, name, d, ROW_NUMBER() OVER (PARTITION BY fid ORDER BY d) AS rn
  FROM pairs
)
SELECT name, d AS nn_dist_m FROM r WHERE rn = 1 ORDER BY d DESC, name LIMIT 5;

WITH pairs AS (
  SELECT a.OGC_FID AS fid, a.NAME AS name, a.FMEL_UPD_D AS upd,
         ST_Distance_Spheroid(a.geometry::GEOMETRY, b.geometry::GEOMETRY) AS d
  FROM sg_parks a
  JOIN sg_parks b ON a.FMEL_UPD_D <> b.FMEL_UPD_D
), r AS (
  SELECT fid, name, upd, d, ROW_NUMBER() OVER (PARTITION BY fid ORDER BY d) AS rn
  FROM pairs
)
SELECT name, upd, d AS nn_dist_m FROM r WHERE rn = 1 ORDER BY d DESC, name LIMIT 3;

WITH ref AS (
  SELECT geometry::GEOMETRY AS g FROM sg_parks WHERE NAME = 'BERLAYER CREEK' LIMIT 1
), d AS (
  SELECT p.FMEL_UPD_D, p.NAME, p.OGC_FID,
         ST_Distance_Spheroid(p.geometry::GEOMETRY, (SELECT g FROM ref)) AS dist_m
  FROM sg_parks p
), r AS (
  SELECT FMEL_UPD_D, NAME, dist_m,
         ROW_NUMBER() OVER (PARTITION BY FMEL_UPD_D ORDER BY dist_m, OGC_FID) AS rn
  FROM d
)
SELECT FMEL_UPD_D, NAME, dist_m FROM r WHERE rn = 2 ORDER BY FMEL_UPD_D;

SELECT ROUND(ST_Distance_Sphere(a.g, b.g) / 1000.0, 2) AS dist_km
FROM (SELECT geometry::GEOMETRY AS g FROM zm_health_facilities WHERE NAME1_ = 'Mukumbi Rhc' ORDER BY ID_ LIMIT 1) a,
     (SELECT geometry::GEOMETRY AS g FROM zm_health_facilities WHERE NAME1_ = 'Siabunkululu' ORDER BY ID_ LIMIT 1) b;

